export const WorkspaceDuplicateInput: z.ZodType<T.WorkspaceDuplicateInput> = struct({ layoutId: optionalField(z.string()), name: optionalField(z.string()), show: optionalField(z.boolean()) }, ["layoutId","name","show"]);
export const WorkspaceListTilesInput: z.ZodType<T.WorkspaceListTilesInput> = struct({ layoutId: optionalField(z.string()) }, ["layoutId"]);
export const WorkspaceMaximizeTileInput: z.ZodType<T.WorkspaceMaximizeTileInput> = struct({ tileId: optionalField(z.string()), kind: optionalField(OpenTileKind), restore: optionalField(z.boolean()), layoutId: optionalField(z.string()) }, ["tileId","kind","restore","layoutId"]);
export const WorkspaceMoveTileInput: z.ZodType<T.WorkspaceMoveTileInput> = struct({ tileId: optionalField(z.string()), kind: optionalField(OpenTileKind), to: TilePlace, layoutId: optionalField(z.string()) }, ["tileId","kind","layoutId"]);
export const WorkspaceOpenTileInput: z.ZodType<T.WorkspaceOpenTileInput> = struct({ kind: OpenTileKind, instrument: optionalField(z.string()), link: optionalField(z.string()), settings: optionalField(JsonValue), placement: optionalField(ChartPlacement), beside: optionalField(z.string()), layoutId: optionalField(z.string()) }, ["instrument","link","settings","placement","beside","layoutId"]);
export const WorkspaceOpenTileOutput: z.ZodType<T.WorkspaceOpenTileOutput> = z.object({ layoutId: z.string(), revision: z.number(), request: TileRequest });
export const WorkspaceSetTileSettingsInput: z.ZodType<T.WorkspaceSetTileSettingsInput> = struct({ tileId: z.string(), settings: JsonValue, layoutId: optionalField(z.string()) }, ["layoutId"]);
export const WorkspaceSetViewInput: z.ZodType<T.WorkspaceSetViewInput> = struct({ left: optionalField(z.boolean()), right: optionalField(z.boolean()), bottom: optionalField(z.boolean()), shareInterval: optionalField(z.boolean()), focus: optionalField(z.boolean()), layoutId: optionalField(z.string()) }, ["left","right","bottom","shareInterval","focus","layoutId"]);
export const WorkspaceTileInput: z.ZodType<T.WorkspaceTileInput> = struct({ tileId: optionalField(z.string()), kind: optionalField(OpenTileKind), layoutId: optionalField(z.string()) }, ["tileId","kind","layoutId"]);
export const WorkspaceTilesOutput: z.ZodType<T.WorkspaceTilesOutput> = z.object({ layoutId: z.string(), revision: z.number(), tiles: z.array(TileInfo), collapsed: z.array(TilePlace) });

